}

/**
 * pi-host 私有数据子目录(agentDir 下)。
 * 注意:不能用 "lxcode" —— Rust 侧 desktop_settings.rs 的 LXCODE_DATA_DIR_NAME
 * 已占用 agentDir/lxcode/(存 DefaultProject 工作区数据)。pi-host 用 "host"。
 */
export function hostDataDir(agentDir: string): string {
  return join(pathResolve(agentDir), "host");
}

export function migrationBackupRoot(agentDir: string, migrationId: string): string {
  return join(hostDataDir(agentDir), "migration-backups", migrationId);
}

export function providerJournalRoot(agentDir: string): string {
  return join(hostDataDir(agentDir), "provider-journal");
}

export function modelBackupDir(agentDir: string): string {
  return join(hostDataDir(agentDir), "model-backups");
}

function sessionArchiveRoot(agentDir: string): string {
  return join(hostDataDir(agentDir), "session-archive");
}

export function attachmentRoot(agentDir: string): string {
  return join(hostDataDir(agentDir), "attachments");
}

export function sessionArchiveDir(agentDir: string, cwd: string): string {
  return join(sessionArchiveRoot(agentDir), workspaceStorageKey(cwd));
}

