 * 数据目录品牌迁移:旧 `agentDir/pideck/` → 新 `agentDir/host/`。
 * 同卷 rename(原子),仅当旧目录存在且新目录不存在时执行。
 * 若两边都在(异常中间态),逐子项 merge,不覆盖已有恢复数据。
 */
export async function migratePideckDirToHost(agentDir: string): Promise<void> {
  const resolvedAgentDir = pathResolve(agentDir);
  await moveLegacyTree(join(resolvedAgentDir, "pideck"), hostDataDir(resolvedAgentDir));
}

